INSERT INTO microscopic_environments (id, orderIndex, name, tagline, description, iconKey, primaryColorHex, secondaryColorHex) VALUES ('oceano_profundo', 3, 'Océano Profundo', 'Muestras traídas desde el mar', 'Examina muestras de agua salada, arrecifes y restos marinos en tu laboratorio.', 'env_oceano', '#0277BD', '#E1F5FE');
INSERT INTO microscopic_environments (id, orderIndex, name, tagline, description, iconKey, primaryColorHex, secondaryColorHex) VALUES ('cuerpo_humano', 4, 'Cuerpo Humano', 'Un laboratorio viviente', 'Observa muestras de células y tejidos para entender cómo funciona tu cuerpo.', 'env_cuerpo', '#C62828', '#FDE8E8');
