INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_paramecio', 'sample_micromundo_01', 'micromundo', 'Paramecio', 'Paramecium caudatum', 'MICROORGANISMO', 'Agua dulce estancada', 'Bacterias y algas microscópicas', 'forma de zapatilla|se mueve con cilios|unicelular', 'Puede expulsar el agua que le sobra con una estructura llamada vacuola contráctil.', 'COMUN', 'disc_paramecio');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_ameba', 'sample_micromundo_01', 'micromundo', 'Ameba', 'Amoeba proteus', 'MICROORGANISMO', 'Estanques y suelos húmedos', 'Bacterias y otros microorganismos', 'cambia de forma constantemente|se mueve con seudópodos|unicelular', 'No tiene una forma fija: la cambia para moverse y para atrapar su alimento.', 'COMUN', 'disc_ameba');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_euglena', 'sample_micromundo_02', 'micromundo', 'Euglena', 'Euglena viridis', 'MICROORGANISMO', 'Agua dulce con luz', 'Fotosíntesis y también absorbe nutrientes', 'tiene un flagelo|un ojo sensible a la luz|verde por clorofila', 'Es mitad planta, mitad animal: hace fotosíntesis pero también nada activamente.', 'POCO_COMUN', 'disc_euglena');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_levadura', 'sample_micromundo_03', 'micromundo', 'Levadura', 'Saccharomyces cerevisiae', 'HONGO', 'Frutas maduras y masas de pan', 'Azúcares', 'unicelular|se reproduce por gemación|produce burbujas de gas', 'Es la responsable de que el pan suba y de que crezca la espuma en algunas bebidas.', 'COMUN', 'disc_levadura');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_tardigrado', 'sample_micromundo_04', 'micromundo', 'Tardígrado', 'Milnesium tardigradum', 'ANIMAL', 'Musgos húmedos', 'Líquidos de plantas y microorganismos', 'ocho patas diminutas|resiste el espacio exterior|se llama ''oso de agua''', 'Puede sobrevivir congelado, deshidratado e incluso en el vacío del espacio.', 'RARO', 'disc_tardigrado');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_diatomea', 'sample_micromundo_02', 'micromundo', 'Diatomea', 'Bacillariophyta', 'MICROORGANISMO', 'Océanos y lagos', 'Fotosíntesis', 'caparazón de vidrio (sílice)|produce gran parte del oxígeno del planeta|forma parte del plancton', 'Las diatomeas producen alrededor de una quinta parte del oxígeno que respiramos.', 'POCO_COMUN', 'disc_diatomea');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_volvox', 'sample_micromundo_04', 'micromundo', 'Volvox', 'Volvox globator', 'MICROORGANISMO', 'Estanques y charcas', 'Fotosíntesis', 'forma colonias esféricas|miles de células trabajando juntas|gira al nadar', 'Aunque es diminuto, el Volvox forma colonias que giran juntas como una pequeña esfera verde.', 'RARO', 'disc_volvox');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_helecho', 'sample_bosque_de_vida_01', 'bosque_de_vida', 'Helecho gigante', 'Polypodiopsida', 'PLANTA', 'Bosque húmedo', 'Fotosíntesis', 'hojas grandes y divididas|se reproduce por esporas|no tiene flores', 'Los helechos existían en la Tierra mucho antes que los dinosaurios.', 'COMUN', 'disc_helecho');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_seta_amanita', 'sample_bosque_de_vida_01', 'bosque_de_vida', 'Seta roja', 'Amanita muscaria', 'HONGO', 'Bosques de coníferas', 'Materia orgánica en descomposición', 'sombrero rojo con puntos blancos|no debe tocarse ni comerse|ayuda a reciclar nutrientes', 'Los hongos no son plantas: forman su propio reino y reciclan la materia del bosque.', 'POCO_COMUN', 'disc_seta');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_conejo', 'sample_bosque_de_vida_02', 'bosque_de_vida', 'Conejo silvestre', 'Oryctolagus cuniculus', 'ANIMAL', 'Praderas y bosques', 'Pasto y hierbas', 'orejas largas|excelente oído|se reproduce rápidamente', 'Un conejo puede girar sus orejas de forma independiente para escuchar en dos direcciones.', 'COMUN', 'disc_conejo');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_zorro', 'sample_bosque_de_vida_02', 'bosque_de_vida', 'Zorro rojo', 'Vulpes vulpes', 'ANIMAL', 'Bosques y zonas mixtas', 'Roedores, conejos e insectos', 'cola espesa|muy adaptable|caza principalmente de noche', 'El zorro puede detectar el campo magnético de la Tierra para calcular sus saltos al cazar.', 'POCO_COMUN', 'disc_zorro');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_mariposa', 'sample_bosque_de_vida_03', 'bosque_de_vida', 'Mariposa monarca', 'Danaus plexippus', 'ANIMAL', 'Praderas y bosques', 'Néctar de flores', 'migra miles de kilómetros|colores naranja y negro|se transforma desde oruga', 'Puede migrar más de 4.000 kilómetros usando el sol como brújula.', 'RARO', 'disc_mariposa');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_buho', 'sample_bosque_de_vida_04', 'bosque_de_vida', 'Búho real', 'Bubo bubo', 'ANIMAL', 'Bosques y acantilados', 'Roedores y aves pequeñas', 'vuelo silencioso|gira la cabeza casi 270°|vista nocturna excelente', 'Sus plumas especiales le permiten volar sin hacer casi ningún ruido.', 'POCO_COMUN', 'disc_buho');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_lince', 'sample_bosque_de_vida_04', 'bosque_de_vida', 'Lince ibérico', 'Lynx pardinus', 'ANIMAL', 'Bosque mediterráneo', 'Conejos principalmente', 'orejas con mechones de pelo|vista y oído extraordinarios|especie protegida', 'Es uno de los felinos más amenazados del mundo, y gracias a la protección va recuperándose.', 'LEGENDARIO', 'disc_lince');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_alga_marina', 'sample_oceano_profundo_02', 'oceano_profundo', 'Alga parda gigante', 'Macrocystis pyrifera', 'PLANTA', 'Bosques submarinos', 'Fotosíntesis', 'puede crecer más de 30 metros|forma auténticos bosques bajo el agua|crece muy rápido', 'Puede crecer hasta 50 centímetros en un solo día bajo condiciones ideales.', 'COMUN', 'disc_alga');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_coral', 'sample_oceano_profundo_02', 'oceano_profundo', 'Coral cerebro', 'Diploria labyrinthiformis', 'ANIMAL', 'Arrecifes tropicales', 'Plancton y luz solar (con algas asociadas)', 'forma colonias de miles de individuos|construye el esqueleto del arrecife|vive en simbiosis con algas', 'Un arrecife de coral puede albergar más especies distintas que cualquier otro ecosistema marino.', 'POCO_COMUN', 'disc_coral');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_medusa', 'sample_oceano_profundo_01', 'oceano_profundo', 'Medusa luna', 'Aurelia aurita', 'ANIMAL', 'Aguas costeras', 'Plancton', 'cuerpo casi transparente|se mueve con pulsaciones|no tiene cerebro ni corazón', 'Está formada en un 95% por agua y existe desde antes que los dinosaurios.', 'POCO_COMUN', 'disc_medusa');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_pulpo', 'sample_oceano_profundo_03', 'oceano_profundo', 'Pulpo común', 'Octopus vulgaris', 'ANIMAL', 'Fondos rocosos', 'Cangrejos y moluscos', 'ocho brazos con ventosas|cambia de color y textura|extremadamente inteligente', 'Tiene tres corazones y su sangre es de color azul.', 'RARO', 'disc_pulpo');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_estrella_mar', 'sample_oceano_profundo_01', 'oceano_profundo', 'Estrella de mar', 'Asteroidea', 'ANIMAL', 'Fondos marinos', 'Moluscos y materia orgánica', 'puede regenerar brazos perdidos|no tiene cerebro|se mueve con cientos de piececillos', 'Si pierde un brazo, puede regenerarlo por completo con el paso del tiempo.', 'POCO_COMUN', 'disc_estrella');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_pez_payaso', 'sample_oceano_profundo_03', 'oceano_profundo', 'Pez payaso', 'Amphiprioninae', 'ANIMAL', 'Arrecifes de coral', 'Algas y pequeños invertebrados', 'vive protegido entre las anémonas|es inmune a su veneno|cambia de sexo durante su vida', 'Vive en una relación de ayuda mutua con la anémona: ella lo protege y él la limpia.', 'POCO_COMUN', 'disc_pez_payaso');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_ballena_azul', 'sample_oceano_profundo_04', 'oceano_profundo', 'Ballena azul', 'Balaenoptera musculus', 'ANIMAL', 'Océano abierto', 'Kril (pequeños crustáceos)', 'el animal más grande del planeta|corazón del tamaño de un auto pequeño|canta bajo el agua', 'A pesar de ser gigantesca, se alimenta de uno de los animales más pequeños del mar: el kril.', 'LEGENDARIO', 'disc_ballena');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_globulo_rojo', 'sample_cuerpo_humano_01', 'cuerpo_humano', 'Glóbulo rojo', 'Erythrocyte', 'MICROORGANISMO', 'Torrente sanguíneo', 'No se alimenta: transporta oxígeno', 'forma de disco|transporta oxígeno por el cuerpo|no tiene núcleo', 'Tu cuerpo produce alrededor de dos millones de glóbulos rojos nuevos cada segundo.', 'COMUN', 'disc_globulo_rojo');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_globulo_blanco', 'sample_cuerpo_humano_01', 'cuerpo_humano', 'Glóbulo blanco', 'Leukocyte', 'MICROORGANISMO', 'Torrente sanguíneo', 'Bacterias y microbios invasores', 'defiende al cuerpo de infecciones|puede salir de los vasos sanguíneos|existen varios tipos', 'Son los soldados del sistema inmunitario: patrullan el cuerpo buscando invasores.', 'POCO_COMUN', 'disc_globulo_blanco');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_neurona', 'sample_cuerpo_humano_02', 'cuerpo_humano', 'Neurona', 'Neuron', 'MICROORGANISMO', 'Cerebro y sistema nervioso', 'Glucosa y oxígeno', 'se comunica con impulsos eléctricos|tiene ramificaciones llamadas dendritas|forma redes complejísimas', 'El cerebro humano tiene unos 86.000 millones de neuronas conectadas entre sí.', 'RARO', 'disc_neurona');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_celula_muscular', 'sample_cuerpo_humano_03', 'cuerpo_humano', 'Célula muscular', 'Myocyte', 'MICROORGANISMO', 'Músculos del cuerpo', 'Glucosa y oxígeno', 'se contrae para generar movimiento|puede alargarse mucho|trabaja en equipo con otras fibras', 'Algunas células musculares pueden medir varios centímetros de largo, muy alargadas.', 'POCO_COMUN', 'disc_celula_muscular');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_plaqueta', 'sample_cuerpo_humano_04', 'cuerpo_humano', 'Plaqueta', 'Thrombocyte', 'MICROORGANISMO', 'Torrente sanguíneo', 'No se alimenta: repara heridas', 'ayuda a cerrar heridas|es más pequeña que un glóbulo rojo|forma coágulos', 'Cuando te cortas, miles de plaquetas corren al lugar para taponar la herida en minutos.', 'COMUN', 'disc_plaqueta');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_pasto', 'sample_ecosistemas_01', 'ecosistemas', 'Pasto de sabana', 'Poaceae', 'PLANTA', 'Sabana africana', 'Fotosíntesis', 'crece rápido tras la lluvia|base de la cadena en la sabana|resiste el pisoteo', 'La sabana puede sostener manadas enteras de herbívoros gracias a su rápido crecimiento.', 'COMUN', 'disc_pasto');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_leon', 'sample_ecosistemas_02', 'ecosistemas', 'León', 'Panthera leo', 'ANIMAL', 'Sabana africana', 'Cebras, ñus y otros herbívoros', 'vive en manadas llamadas orgullos|las hembras cazan en equipo|es el depredador tope de la sabana', 'Las leonas hacen la mayoría de las cacerías, a menudo trabajando en equipo.', 'POCO_COMUN', 'disc_leon');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_nenufar', 'sample_ecosistemas_03', 'ecosistemas', 'Nenúfar', 'Nymphaea', 'PLANTA', 'Estanque de agua dulce', 'Fotosíntesis', 'hojas flotantes|raíces ancladas al fondo|flores que se abren de día', 'Sus hojas flotantes son tan resistentes que pueden sostener el peso de una pequeña rana.', 'COMUN', 'disc_nenufar');
INSERT INTO microscope_discoveries (id, sampleId, environmentId, name, scientificName, category, habitat, diet, characteristics, curiosity, rarity, iconKey) VALUES ('disc_hongo_reciclador', 'sample_ecosistemas_04', 'ecosistemas', 'Hongo reciclador de estanque', 'Saprolegnia sp.', 'HONGO', 'Estanque de agua dulce', 'Materia orgánica en descomposición', 'descompone restos de plantas y animales|libera nutrientes de vuelta al agua|invisible a simple vista en su mayoría', 'Sin descomponedores como este hongo, los nutrientes nunca volverían a estar disponibles.', 'POCO_COMUN', 'disc_hongo_reciclador');
INSERT INTO cell_models (id, name, cellType, description) VALUES ('cell_animal', 'Célula animal', 'Animal', 'La unidad básica de todos los animales, incluido tú.');
INSERT INTO cell_models (id, name, cellType, description) VALUES ('cell_vegetal', 'Célula vegetal', 'Vegetal', 'La unidad básica de todas las plantas del Bosque de Vida.');
INSERT INTO cell_models (id, name, cellType, description) VALUES ('cell_bacteriana', 'Célula bacteriana', 'Bacteriana', 'Mucho más simple: no tiene núcleo definido.');
INSERT INTO cell_structures (id, cellModelId, name, function, xPercent, yPercent) VALUES ('cell_animal_nucleo', 'cell_animal', 'Núcleo', 'Controla las actividades de la célula y guarda el ADN.', 0.5, 0.5);
INSERT INTO cell_structures (id, cellModelId, name, function, xPercent, yPercent) VALUES ('cell_animal_membrana', 'cell_animal', 'Membrana celular', 'Protege la célula y controla lo que entra y sale.', 0.12, 0.5);
INSERT INTO cell_structures (id, cellModelId, name, function, xPercent, yPercent) VALUES ('cell_animal_citoplasma', 'cell_animal', 'Citoplasma', 'Sustancia gelatinosa donde ocurren las reacciones de la célula.', 0.3, 0.75);
INSERT INTO cell_structures (id, cellModelId, name, function, xPercent, yPercent) VALUES ('cell_animal_mitocondria', 'cell_animal', 'Mitocondria', 'Genera la energía que la célula necesita para funcionar.', 0.7, 0.3);
INSERT INTO cell_structures (id, cellModelId, name, function, xPercent, yPercent) VALUES ('cell_vegetal_nucleo', 'cell_vegetal', 'Núcleo', 'Controla las actividades de la célula y guarda el ADN.', 0.5, 0.5);
INSERT INTO cell_structures (id, cellModelId, name, function, xPercent, yPercent) VALUES ('cell_vegetal_pared', 'cell_vegetal', 'Pared celular', 'Capa rígida que da forma y soporte a la célula.', 0.08, 0.5);
INSERT INTO cell_structures (id, cellModelId, name, function, xPercent, yPercent) VALUES ('cell_vegetal_cloroplasto', 'cell_vegetal', 'Cloroplasto', 'Realiza la fotosíntesis para producir energía a partir de la luz.', 0.7, 0.35);
